app.MapPost("/api/upload/avatar", async (HttpRequest req) => { var form = await req.ReadFormAsync(); var f = form.Files.FirstOrDefault(); if (f is null) return Results.BadRequest("missing file"); var ext = Path.GetExtension(f.FileName).ToLowerInvariant(); if (ext is not ".png" and not ".jpg" and not ".jpeg") return Results.BadRequest("blocked file type"); var safeName = Path.GetRandomFileName() + ext; var dest = Path.Combine("/data/uploads", safeName); await using var fs = File.Create(dest); await f.CopyToAsync(fs); return Results.Json(new { ok = true, file = safeName }); });
