static bool VerifyToken(HttpRequest req) => req.Headers.TryGetValue("X-Verify-Token", out var v) && v == (Environment.GetEnvironmentVariable("VERIFY_TOKEN") ?? "benchsecret");
static System.Text.Json.JsonSerializerOptions JsonOpts() => new() { PropertyNameCaseInsensitive = true };
